// ---------------------------------------------------------------------------
// Generates n8n/score-batch.gen.js - the body of Stage 2's "Score Batch" Code
// node - by INLINING the tested sources rather than hand-porting them.
//
// A hand-copied scorer that drifts from the one the harness proves is exactly
// how the 2026-08-18 false findings survived review. The generated file is both
// a valid n8n Code-node body AND a requireable module, so test-node-parity.js
// can run the shipped code itself against the same expectations.
//
//   node n8n/build-score-node.js     # regenerate
//   node test-node-parity.js         # prove the generated body still agrees
// ---------------------------------------------------------------------------

const fs = require('fs');
const path = require('path');

const DIR = path.join(__dirname, '..');
const read = function (f) { return fs.readFileSync(path.join(DIR, f), 'utf8'); };

// Pulls a top-level `function NAME(...) { ... }` out of a source file by
// matching braces. Throws rather than emitting a truncated function.
function extractFn(src, name) {
  const start = src.indexOf('function ' + name + '(');
  if (start === -1) throw new Error('function not found: ' + name);
  let i = src.indexOf('{', start);
  let depth = 0;
  for (; i < src.length; i++) {
    if (src[i] === '{') depth++;
    else if (src[i] === '}') { depth--; if (depth === 0) return src.slice(start, i + 1); }
  }
  throw new Error('unbalanced braces while extracting ' + name);
}

function stripModule(src) {
  return src
    .split('\n')
    .filter(function (l) { return !/^const \{.*\} = require\(/.test(l) && !/^module\.exports/.test(l); })
    .join('\n')
    .trim();
}

const scorer = read('scorer.js');
const helpers = ['parseCardDate', 'bucketOf', 'priceAt', 'parseDiscount']
  .map(function (n) { return extractFn(scorer, n); })
  .join('\n\n');

const body = [
  '// =========================================================================',
  '// GENERATED by n8n/build-score-node.js - DO NOT EDIT HERE.',
  '// Sources: paymentsinfo.js, scorer.js (4 helpers), scorer-month.js.',
  '// Edit those, run `node n8n/build-score-node.js`, then `node test-node-parity.js`.',
  '// =========================================================================',
  '',
  '// --- from scorer.js: the four helpers scorer-month.js imports ------------',
  helpers,
  '',
  '// --- from paymentsinfo.js -----------------------------------------------',
  stripModule(read('paymentsinfo.js')),
  '',
  '// --- from scorer-month.js -----------------------------------------------',
  stripModule(read('scorer-month.js')),
  '',
  read('n8n/score-glue.js').trim(),
  '',
].join('\n');

fs.writeFileSync(path.join(__dirname, 'score-batch.gen.js'), body);
console.log('wrote n8n/score-batch.gen.js (' + body.split('\n').length + ' lines)');
